/// <summary>
/// Service class for transfer picking list generation service
/// </summary>
class METTransferPickingListGenerationService extends SysOperationServiceBase
{
    METTransferPickingListGenerationContract    dataContract;
    BatchHeader                                 batchHeader;

}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METTransferPickingListGenerationContract _dataContract)
    {
        dataContract = _dataContract;

        this.initialise();
        this.processTasks();
    }

/// <summary>Initialise global variables</summary>
public void initialise()
{
    batchHeader         = BatchHeader::construct();
}

    /// <summary>Create sub tasks that do the actual calculations</summary>
    public void processTasks()
    {
        int i;
        METTransferPickingListGenerationTaskController          transferPickingListGenerationTaskController;
        METTransferPickingListGenerationTaskContract            transferPickingListGenerationTaskContract;

        for(i = 1; i <= conLen(dataContract.parmTransferOrderList()); i++)
        {
            transferPickingListGenerationTaskController = METTransferPickingListGenerationTaskController::construct();
            transferPickingListGenerationTaskContract   = this.buildDataContract(transferPickingListGenerationTaskController, conPeek(dataContract.parmTransferOrderList(), i));
            batchHeader.addTask(transferPickingListGenerationTaskController);
        }

        batchHeader.parmCaption(strFmt('%1 by %2', "@MET:MetPickingListGeneration", curUserId()));
        batchHeader.save();
    }

/// <summary>
/// contract METTransferPickingListGenerationTaskContract
/// </summary>
/// <param name = "_taskController">METTransferPickingListGenerationTaskController</param>
/// <param name = "_transferOrderList">transfer order list</param>
/// <returns>METTransferPickingListGenerationTaskContract</returns>
public METTransferPickingListGenerationTaskContract buildDataContract(METTransferPickingListGenerationTaskController _taskController, container _transferOrderList)
{
    METTransferPickingListGenerationTaskContract   transferPickingListGenerationTaskContract;
    
    transferPickingListGenerationTaskContract = _taskController.getDataContractObject();
    transferPickingListGenerationTaskContract.parmTransferId(conPeek(_transferOrderList, 1));
    transferPickingListGenerationTaskContract.parmOSCCodeList(conDel(_transferOrderList, 1, 1));
    
    return transferPickingListGenerationTaskContract;
}
